<?phpsession_start();// Redirect if not logged inif (!isset($_SESSION['username'])) {    header("Location: login.php");    exit;}// DB connection$host = 'localhost';$dbname = 'moviedb';$username = 'root';$password = '';$port = 3307;$conn = new mysqli($host, $username, $password, $dbname, $port);if ($conn->connect_error) {    die("Connection failed: " . $conn->connect_error);}// Delete user from DB$user = $_SESSION['username'];$sql = "DELETE FROM users WHERE username = ?";$stmt = $conn->prepare($sql);$stmt->bind_param("s", $user);if ($stmt->execute()) {    session_destroy();    header("Location: signup.php?message=account_deleted");    exit;} else {    echo "Error deleting profile. Please try again.";}$conn->close();?>